def main():
    print(f"📦 [Seed] 균형 있게 엄선된 글로벌 장소 데이터: {len(GLOBAL_PLACES)}개 준비 완료!")
    
    existing_places = []
    if os.path.exists(DATA_PATH):
        with open(DATA_PATH, "r", encoding="utf-8") as f:
            try:
                existing_places = json.load(f)
            except Exception:
                existing_places = []
    
    places_dict = {p["id"]: p for p in existing_places}
    for p in GLOBAL_PLACES:
        places_dict[p["id"]] = p
        
    merged_list = list(places_dict.values())
    
    os.makedirs(os.path.dirname(DATA_PATH), exist_ok=True)
    with open(DATA_PATH, "w", encoding="utf-8") as f:
        json.dump(merged_list, f, ensure_ascii=False, indent=4)
        
    print(f"✅ [저장 성공] 총 {len(merged_list)}개 장소 데이터가 '{DATA_PATH}'에 병합 저장되었습니다!")

if __name__ == "__main__":
    main()
